interface ServerOptions { host?: string; port?: number; tls?: boolean }
const defaults: Required<ServerOptions> = { host: 'localhost', port: 8080, tls: false };

function resolveOptions(overrides: ServerOptions = {}): Required<ServerOptions> {
  return { ...defaults, ...overrides };
}

createServer(resolveOptions({ port: 9000 }));
